using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

public sealed class RegistroConsultas
{
    private readonly List<string> _estudiantes = [];
    private readonly List<RecursoConsultado> _recursos = [];
    private readonly List<DatoConsultado> _datos = [];
    private readonly List<Cita> _citas = [];
    private readonly SortedSet<int> _entradasDeReglas = [];
    private readonly List<string> _fuentes = [];

    public IReadOnlyList<string> Estudiantes => _estudiantes;

    public IReadOnlyList<RecursoConsultado> Recursos => _recursos;

    public IReadOnlyList<DatoConsultado> DatosConsultados => _datos;

    public IReadOnlyList<Cita> Citas => _citas;


    public IReadOnlyList<Cita> Reglas => ReglasAplicadas.Citas(_entradasDeReglas);

    public IReadOnlyList<string> Fuentes => _fuentes;

    public bool UsoDatos => _estudiantes.Count > 0;

    public void Registrar(string estudianteId, IEnumerable<RecursoConsultado> recursos, Cita? cita)
    {
        AgregarSiFalta(_estudiantes, estudianteId);
        foreach (var recurso in recursos)
        {
            AgregarSiFalta(_recursos, recurso);
        }

        if (cita is not null)
        {
            AgregarSiFalta(_citas, cita);
        }
    }

    public void RegistrarVerificacion(IEnumerable<RecursoConsultado> recursos, IEnumerable<DatoConsultado> datos)
    {
        foreach (var recurso in recursos)
        {
            AgregarSiFalta(_recursos, recurso);
        }

        RegistrarDatos(datos);
    }

    public void RegistrarDatos(IEnumerable<DatoConsultado> datos)
    {
        foreach (var dato in datos)
        {
            AgregarSiFalta(_datos, dato);
        }
    }

    public void RegistrarReglas(IEnumerable<Cita> reglas)
    {
        foreach (var regla in reglas)
        {
            AgregarSiFalta(_reglas, regla);
        }
    }

    public void RegistrarCita(Cita cita) => AgregarSiFalta(_citas, cita);

    public void AgregarFuente(string texto) => _fuentes.Add(texto);

    private static void AgregarSiFalta<T>(List<T> lista, T valor)
    {
        if (!lista.Contains(valor))
        {
            lista.Add(valor);
        }
    }
}

using TutorFlow.Core.Academico;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

internal sealed record ResumenEntregado(string Texto, IReadOnlyList<Cita> Reglas);

internal static class FormateadorResumen
{
    public static ResumenEntregado Resumir(ResumenEstudiante resumen)
    {
        var reglas = ReglasDe(resumen);
        var lineas = resumen.Asignaturas.Select(LineaDeAsignatura).ToList();
        lineas.Add($"Promedio ponderado del periodo: {FormateadorDatos.Promedio(resumen.Promedio)}.");
        lineas.Add($"Créditos matriculados: {resumen.CreditosMatriculados}.");
        lineas.Add($"Prueba académica: {(resumen.PruebaAcademica ? "sí" : "no")}.");
        lineas.Add($"Beca por rendimiento: {FormateadorDatos.TextoBeca(resumen.Beca)}.");
        lineas.Add(LineaDeReglas(reglas));
        return new ResumenEntregado(string.Join("\n", lineas), reglas);
    }

    public static string LineaDeReglas(IReadOnlyList<Cita> reglas) =>
        $"Reglas aplicadas a estos datos: {string.Join("; ", reglas.Select(Describir))}.";

    private static string LineaDeAsignatura(ResultadoAsignatura resultado)
    {
        var asignatura = resultado.Asignatura;
        return $"{asignatura.Nombre} ({asignatura.Codigo}, {asignatura.Creditos} créditos): "
            + $"{FormateadorDatos.DescribirEstado(resultado)}; asistencia: {FormateadorDatos.DescribirAsistencia(resultado)}.";
    }

    private static IReadOnlyList<Cita> ReglasDe(ResumenEstudiante resumen)
    {
        IReadOnlyList<ResumenEstudiante> resumenes = [resumen];
        return [.. ReglasAplicadas.DeNotas(resumenes).Concat(ReglasAplicadas.DeAsistencia(resumenes)).Distinct()];
    }

    private static string Describir(Cita cita) => $"{cita.Documento} · {cita.Seccion}";
}

